@Component("paymentOrder-handler")
@ProcessingGroup("paymentOrder-processing-group")
public class PaymentOrderEventHandler {
	
	// core constructor
	PaymentOrderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePaymentOrderEvent
     */
    @EventHandler
    public void handle( CreatePaymentOrderEvent event) {
        entityManager.persist(new PaymentOrder(event.getPaymentOrderId(), event.getOrderReference(), event.getRequestedExecutionDate(), event.getPurpose(), event.getSourceAccount(), event.getDestinationAccount(), event.getBeneficiary(), event.getTransactions(), event.getFxDeal(), event.getFees(), event.getPaymentMethod(), event.getStatus(), event.getPriority()));
    }

    /*
     * @param	event UpdatePaymentOrderEvent
     */
    @EventHandler
    public PaymentOrder handle( UpdatePaymentOrderEvent event) {
    	entityManager.merge(new PaymentOrder(event.getPaymentOrderId(), event.getOrderReference(), event.getRequestedExecutionDate(), event.getPurpose(), event.getSourceAccount(), event.getDestinationAccount(), event.getBeneficiary(), event.getTransactions(), event.getFxDeal(), event.getFees(), event.getPaymentMethod(), event.getStatus(), event.getPriority()));
    }
    
    /*
     * @param	event DeletePaymentOrderEvent
     */
    @EventHandler
    public void on( DeletePaymentOrderEvent event) {
    	PaymentOrder entity = new PaymentOrder();
   
    	// ------------------------------------------
    	// apply the PaymentOrderId
    	// ------------------------------------------
    	entity.setPaymentOrderId( event.getPaymentOrderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PaymentOrderRepository paymentOrderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PaymentOrderEventHandler.class.getName());

}
